{
  "flashcards": [
    {
      "front": "What is the primary purpose of a star schema in dimensional modeling?",
      "back": "To simplify queries and optimize performance by denormalizing data into a central fact table surrounded by dimension tables, minimizing complex joins.",
      "requirement_ids": ["r3"]
    },
    {
      "front": "What is a slowly changing dimension (SCD) Type 2?",
      "back": "A technique to track historical data by adding new rows for changes, typically using effective start/end dates and a current flag to preserve history.",
      "requirement_ids": ["r3"]
    },
    {
      "front": "How do you handle backfills in production data pipelines?",
      "back": "Use idempotent tasks that can be safely re-run without duplicating data, often by overwriting partitions or using 'delete-then-insert' patterns.",
      "requirement_ids": ["r4"]
    },
    {
      "front": "What is the difference between a fact table and a dimension table?",
      "back": "Fact tables store quantitative metrics (measures) and foreign keys to dimensions. Dimension tables store descriptive attributes (context) like product names or locations.",
      "requirement_ids": ["r3"]
    },
    {
      "front": "In Python, what is the difference between a list comprehension and a generator expression?",
      "back": "List comprehensions create the entire list in memory immediately. Generator expressions create an iterator, computing values on-the-fly, which is more memory-efficient for large datasets.",
      "requirement_ids": ["r1"]
    },
    {
      "front": "What are Airflow 'Sensors'?",
      "back": "Specialized operators that wait for an external event or condition (like a file appearing in S3 or a database partition) before allowing the downstream task to proceed.",
      "requirement_ids": ["r5"]
    },
    {
      "front": "How does Dagster differ from Airflow regarding data awareness?",
      "back": "Dagster is 'data-aware' and focuses on data assets and their dependencies, whereas Airflow is primarily task-aware, focusing on the execution sequence of operators.",
      "requirement_ids": ["r5", "r6"]
    },
    {
      "front": "What is the purpose of a CTE (Common Table Expression) in SQL?",
      "back": "To improve query readability and maintainability by breaking complex logic into named temporary result sets that exist only during the execution of the query.",
      "requirement_ids": ["r2"]
    },
    {
      "front": "Why is idempotency critical in production data pipelines?",
      "back": "It ensures that running a pipeline multiple times with the same input produces the same output, allowing for safe retries after failures without corrupting data.",
      "requirement_ids": ["r4"]
    },
    {
      "front": "What is the difference between a LEFT JOIN and an INNER JOIN?",
      "back": "INNER JOIN returns only rows with matches in both tables. LEFT JOIN returns all rows from the left table, filling with NULLs where no match exists in the right table.",
      "requirement_ids": ["r2"]
    },
    {
      "front": "What is a Python decorator?",
      "back": "A function that takes another function as an argument and extends its behavior without explicitly modifying the original function's source code.",
      "requirement_ids": ["r1"]
    },
    {
      "front": "What is a Dagster 'Asset'?",
      "back": "A software object that models a data artifact (like a table or file) and its lineage, allowing Dagster to track when the data was last updated and by what process.",
      "requirement_ids": ["r6"]
    }
  ]
}
